    c0 = ap.step(0, packets, known_targets)
    if c0: queue[4] = c0; next_free_tick = 5
    for tk in range(1, 421):
        sol = min(100.0 - bat, eff * solar_unit(tk, rules))
        bat += sol - 0.15
        cmd = queue.pop(tk, None)
        events = []; h_rep=0.0; w_odo=0.0; v_odo=0.0
        if cmd:
            if cmd['action']=='drive':
                heading_bias += rng.gauss(0.0, 0.2)
                h_eff = cmd['heading_deg'] + heading_bias + rng.gauss(0.0, 1.5)
                res = drive(surf, rules['physics'], true_x, true_y, h_eff, cmd['metres'], slip_base, noise=rng.uniform(-0.02,0.02), battery=bat)
                true_x, true_y = res['x'], res['y']; bat -= res['energy']
