                    events.append({'type':'safety_stop','reason':res['stop']}); queue.clear()
            elif cmd['action']=='sample':
                bat -= 2.0
                for t in all_targets:
                    if t['id'] not in sampled and t['appear_tick']<=tk and math.hypot(t['x']-true_x, t['y']-true_y)<=2.5:
                        sampled.add(t['id']); break
        for dt in discoveries:
            if dt['appear_tick']==tk: events.append({'type':'target_discovered','target_id':dt['id']})
        ox = max(0,min(600,true_x+rng.gauss(0,1))); oy = max(0,min(400,true_y+rng.gauss(0,1)))
        packets.append({'tick':tk,'received_tick':tk+3,'position':[ox,oy],'heading_deg':h_rep,'battery':bat,'charge':sol,'terrain':surf.terrain(true_x,true_y),'tilt':round(surf.slope(true_x,true_y),3),'wheel_odometry':w_odo,'visual_odometry':v_odo,'sampled_targets':sorted(sampled),'alive':True,'events':events})
        arr = [p for p in packets if p['received_tick']==tk]
        for p in arr:
            for ev in p['events']:
                if ev.get('type')=='target_discovered':
                    for dt in discoveries:
                        if dt['id']==ev['target_id']: known_targets.append(dict(dt))
        if tk < 420:
            prev_end = ap.endgame_base_only
            prev_route = list(ap.route)
            cout = ap.step(tk, arr, known_targets)
            if ap.endgame_base_only and not prev_end:
                print(f'  ENDGAME triggered at tick {tk}! bat={bat:.1f}, pos=({true_x:.1f},{true_y:.1f}), route_was={prev_route}')
